create table alarm_rules(id varchar(36) primary key,project_id varchar(100) not null,name varchar(200) not null,source varchar(30) not null,severity varchar(20) not null,metric varchar(40) not null,operator varchar(8) not null,threshold double precision not null,duration_seconds integer not null default 0,enabled boolean not null default false,target_ids text not null default '[]',notification_channels text not null default '["IN_APP"]',version bigint not null default 1,updated_at timestamptz not null default current_timestamp);
create table alarms(id varchar(36) primary key,project_id varchar(100) not null,rule_id varchar(36),source varchar(30) not null,target_id varchar(200) not null,mode varchar(20) not null,severity varchar(20) not null,content text not null,status varchar(30) not null default 'OPEN',observed_recovery boolean not null default false,dedupe_key varchar(500) not null,version bigint not null default 1,created_at timestamptz not null default current_timestamp,updated_at timestamptz not null default current_timestamp);
create unique index alarms_active_dedupe on alarms(dedupe_key) where observed_recovery=false;
create index alarms_project_time on alarms(project_id,created_at desc);
create table alarm_actions(id varchar(36) primary key,alarm_id varchar(36) not null references alarms(id),actor varchar(160) not null,status varchar(30) not null,note text not null,created_at timestamptz not null default current_timestamp);
create table notifications(id varchar(36) primary key,project_id varchar(100) not null,alarm_id varchar(36),recipient_id varchar(160) not null,channel varchar(20) not null,status varchar(30) not null,message text not null,is_read boolean not null default false,attempts integer not null default 0,last_error text,created_at timestamptz not null default current_timestamp,unique(alarm_id,recipient_id,channel));
create table observations(id varchar(36) primary key,project_id varchar(100) not null,asset_id varchar(200) not null,mode varchar(20) not null,metrics text not null,external_event_id varchar(200) not null,observed_at timestamptz not null,received_at timestamptz not null default current_timestamp,unique(project_id,external_event_id));
create index observation_asset_time on observations(project_id,asset_id,observed_at desc);
create table alarm_rule_states(rule_id varchar(36) not null,asset_id varchar(200) not null,breach_since timestamptz,observed_at timestamptz not null,primary key(rule_id,asset_id));
